/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {matchPath} from '@docusaurus/router';
import isInternalUrl, {
  getInternalPathParts,
  hasProtocol,
} from '@docusaurus/isInternalUrl';
import {
  DefaultNumberPrefixParser,
  stripNumberPrefix,
  stripPathNumberPrefixes,
} from '../numberPrefix';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,
  ActiveDocContext,
  DocVersionSuggestions,
} from '@docusaurus/plugin-content-docs/client';
import type {UseDataOptions} from '@docusaurus/types';

// This code is not part of the api surface, not in ./theme on purpose

// get the data of the plugin that is currently "active"
// ie the docs of that plugin are currently browsed
// it is useful to support multiple docs plugin instances
export function getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  const activeEntry = Object.entries(allPluginData)
    // Route sorting: '/android/foo' should match '/android' instead of '/'
    .sort((a, b) => b[1].path.localeCompare(a[1].path))
    .find(
      ([, pluginData]) =>
        !!matchPath(pathname, {
          path: pluginData.path,
          exact: false,
          strict: false,
        }),
    );

  const activePlugin: ActivePlugin | undefined = activeEntry
    ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
    : undefined;

  if (!activePlugin && options.failfast) {
    throw new Error(
      `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
        allPluginData,
      )
        .map((plugin) => plugin.path)
        .join(', ')}`,
    );
  }

  return activePlugin;
}

export const getLatestVersion = (data: GlobalPluginData): GlobalVersion =>
  data.versions.find((version) => version.isLast)!;

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  const versions = data.versions;
  const lastVersion = getLatestVersion(data);
  const locationIsInternal = isInternalUrl(pathname);
  const locationHasProtocol = hasProtocol(pathname);
  const locationParts = getInternalPathParts(pathname);
  const locationCanonical = locationParts
    ? locationParts.withoutTrailingSlash
    : pathname;
  const locationTrailing = locationParts
    ? locationParts.withTrailingSlash
    : pathname;
  const strippedLocationPath = stripPathNumberPrefixes(
    locationCanonical,
    DefaultNumberPrefixParser,
  );
  const locationSegments: string[] = [];
  const locationPathCandidates: string[] = [pathname, locationCanonical];

  if (locationTrailing !== pathname) {
    locationPathCandidates.push(locationTrailing);
  }
  if (strippedLocationPath !== locationCanonical) {
    locationPathCandidates.push(strippedLocationPath);
  }

  if (data) {
    if (typeof pathname === 'string') {
      if (locationParts) {
        const rawLocationSegments = locationParts.segments;
        for (
          let segmentIndex = 0;
          segmentIndex < rawLocationSegments.length;
          segmentIndex += 1
        ) {
          const rawSegment = rawLocationSegments[segmentIndex];
          if (rawSegment) {
            const strippedSegment = stripNumberPrefix(
              rawSegment,
              DefaultNumberPrefixParser,
            );
            const comparable =
              strippedSegment.length > 0 ? strippedSegment : rawSegment;
            locationSegments.push(comparable.toLowerCase());
          }
        }
      } else {
        const fallbackSegments = pathname.split('/');
        for (
          let segmentIndex = 0;
          segmentIndex < fallbackSegments.length;
          segmentIndex += 1
        ) {
          const rawSegment = fallbackSegments[segmentIndex];
          if (rawSegment) {
            locationSegments.push(rawSegment.toLowerCase());
          }
        }
      }

      const joinedLocationSegments = locationSegments.join('/');
      const locationDepth = locationSegments.length;
      const analyzedVersions: {
        version: GlobalVersion;
        parts: ReturnType<typeof getInternalPathParts>;
        strippedPath: string;
        depth: number;
        hasPatternTokens: boolean;
        comparableSegments: string[];
        pathCandidates: string[];
        joinedSegments: string;
      }[] = [];

      for (
        let versionIndex = 0;
        versionIndex < versions.length;
        versionIndex += 1
      ) {
        const version = versions[versionIndex];
        if (version) {
          const versionParts = getInternalPathParts(version.path);
          const versionCanonical = versionParts
            ? versionParts.withoutTrailingSlash
            : version.path;
          const strippedPath = stripPathNumberPrefixes(
            versionCanonical,
            DefaultNumberPrefixParser,
          );
          const comparableSegments: string[] = [];
          const pathCandidates: string[] = [version.path, versionCanonical];

          if (versionParts) {
            pathCandidates.push(
              versionParts.withLeadingSlash,
              versionParts.withTrailingSlash,
            );
            const rawVersionSegments = versionParts.segments;
            for (
              let segmentIndex = 0;
              segmentIndex < rawVersionSegments.length;
              segmentIndex += 1
            ) {
              const rawSegment = rawVersionSegments[segmentIndex];
              if (rawSegment) {
                const strippedSegment = stripNumberPrefix(
                  rawSegment,
                  DefaultNumberPrefixParser,
                );
                const comparable =
                  strippedSegment.length > 0 ? strippedSegment : rawSegment;
                comparableSegments.push(comparable.toLowerCase());
              }
            }
          } else {
            const rawSegments = version.path.split('/');
            for (
              let segmentIndex = 0;
              segmentIndex < rawSegments.length;
              segmentIndex += 1
            ) {
              const rawSegment = rawSegments[segmentIndex];
              if (rawSegment) {
                comparableSegments.push(rawSegment.toLowerCase());
              }
            }
          }

          if (strippedPath !== versionCanonical) {
            pathCandidates.push(strippedPath);
          }

          analyzedVersions.push({
            version,
            parts: versionParts,
            strippedPath,
            depth: comparableSegments.length,
            hasPatternTokens: /[:*?()+]/.test(version.path),
            comparableSegments,
            pathCandidates,
            joinedSegments: comparableSegments.join('/'),
          });
        }
      }

      // Last version is a route like /docs/*,
      // we need to match it last or it would match /docs/version-1.0/* as well
      const orderedVersionsMetadata = [
        ...analyzedVersions.filter((entry) => entry.version !== lastVersion),
        analyzedVersions.find((entry) => entry.version === lastVersion),
      ];

      for (
        let orderedIndex = 0;
        orderedIndex < orderedVersionsMetadata.length;
        orderedIndex += 1
      ) {
        const analyzed = orderedVersionsMetadata[orderedIndex];
        const version = analyzed ? analyzed.version : lastVersion;
        const versionPath = version.path;
        let shouldAttemptMatch = true;

        if (analyzed) {
          if (!analyzed.hasPatternTokens) {
            shouldAttemptMatch = false;
            const versionParts = analyzed.parts;
            const versionSegments = analyzed.comparableSegments;
            const pathCandidates = analyzed.pathCandidates;
            const versionDepth = analyzed.depth;
            const joinedVersionSegments = analyzed.joinedSegments;
            const normalizedLocation =
              strippedLocationPath.length > 0
                ? strippedLocationPath.toLowerCase()
                : pathname.toLowerCase();
            const normalizedVersion = analyzed.strippedPath.toLowerCase();

            if (locationHasProtocol && !locationIsInternal) {
              shouldAttemptMatch = true;
            }

            if (!shouldAttemptMatch) {
              if (!versionParts) {
                shouldAttemptMatch =
                  pathCandidates.includes(pathname) ||
                  pathname.startsWith(`${versionPath}/`) ||
                  versionPath.length === 0;
              } else if (versionDepth === 0) {
                shouldAttemptMatch =
                  pathname.startsWith('/') || locationParts !== undefined;
              } else if (
                pathCandidates.includes(pathname) ||
                pathCandidates.includes(locationCanonical) ||
                pathCandidates.includes(locationTrailing)
              ) {
                shouldAttemptMatch = true;
              } else {
                let prefixMatches = versionDepth <= locationDepth;
                for (
                  let depth = 0;
                  prefixMatches && depth < versionDepth;
                  depth += 1
                ) {
                  const wanted = versionSegments[depth];
                  const actual = locationSegments[depth];
                  const actualStripped = actual
                    ? stripNumberPrefix(actual, DefaultNumberPrefixParser)
                    : '';
                  prefixMatches = Boolean(
                    wanted &&
                      actual &&
                      (wanted === actual || actualStripped === wanted),
                  );
                }

                prefixMatches =
                  prefixMatches ||
                  joinedLocationSegments === joinedVersionSegments ||
                  joinedLocationSegments.startsWith(
                    `${joinedVersionSegments}/`,
                  ) ||
                  (analyzed.strippedPath.length > 0 &&
                    (normalizedLocation === normalizedVersion ||
                      normalizedLocation.startsWith(`${normalizedVersion}/`)));

                const docs = version.docs;
                for (
                  let docIndex = 0;
                  !prefixMatches &&
                  Array.isArray(docs) &&
                  docIndex < docs.length;
                  docIndex += 1
                ) {
                  const doc = docs[docIndex];
                  const docPath = doc ? doc.path : undefined;
                  const docParts = docPath
                    ? getInternalPathParts(docPath)
                    : undefined;
                  const docCanonical = docParts
                    ? docParts.withoutTrailingSlash
                    : docPath;
                  prefixMatches = Boolean(
                    docPath &&
                      (pathname === docPath ||
                        pathname.startsWith(`${docPath}/`) ||
                        (docCanonical !== undefined &&
                          locationPathCandidates.includes(docCanonical))),
                  );
                }

                shouldAttemptMatch = prefixMatches;
              }
            }
          }
        }

        if (shouldAttemptMatch) {
          const matched = matchPath(pathname, {
            path: versionPath,
            exact: false,
            strict: false,
          });
          if (matched) {
            return version;
          }
        }
      }
    }
  }

  return undefined;
}

export function getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  const activeVersion = getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

  function getAlternateVersionDocs(
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    const result: ActiveDocContext['alternateDocVersions'] = {};
    data.versions.forEach((version) => {
      version.docs.forEach((doc) => {
        if (doc.id === docId) {
          result[version.name] = doc;
        }
      });
    });
    return result;
  }

  const alternateVersionDocs = activeDoc
    ? getAlternateVersionDocs(activeDoc.id)
    : {};

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

export function getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = getLatestVersion(data);
  const activeDocContext = getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
}

